    ranked_wrapper = _growth_direct_eval_rank_candidates([dict(candidate_b), dict(wrapper_candidate)])
    ranked_module = direct_module.rank_growth_direct_eval_candidates([dict(candidate_b), dict(wrapper_candidate)])
