# 65. Growth opportunity review package helper
# ---------------------------------------------------------------------------

def check_growth_opportunity_review_package_helper() -> None:
    """Growth opportunity review packages summarize business readiness read-only."""
    from link_modes.growth.link_growth_console import (
        collect_growth_business_evidence_contract,
        collect_growth_business_opportunity_scan,
        collect_growth_opportunity_review_package,
        parse_growth_opportunity_review_package_json,
        stable_growth_opportunity_review_package_json,
        validate_growth_opportunity_review_package,
    )

    scan = collect_growth_business_opportunity_scan()
    contract = collect_growth_business_evidence_contract(scan)
    package = collect_growth_opportunity_review_package(scan, contract)
    same = collect_growth_opportunity_review_package(scan, contract)
    validate_growth_opportunity_review_package(package, scan, contract)
    _require(package["growth_opportunity_review_package_id"] == same["growth_opportunity_review_package_id"],
             "growth opportunity review package id must be deterministic")
    _require(package["growth_business_opportunity_scan_id"] == scan["growth_business_opportunity_scan_id"],
             "growth opportunity review package must preserve scan id")
    _require(package["growth_business_evidence_contract_id"] == contract["growth_business_evidence_contract_id"],
             "growth opportunity review package must preserve evidence contract id")
    _require(package["opportunity_status"] == "pass",
             "default growth opportunity review package must pass opportunity status")
    _require(package["evidence_status"] == "block",
             "default growth opportunity review package must block on missing evidence")
    _require(package["approval_status"] == "review",
             "default growth opportunity review package must require approval review")
    _require(package["risk_status"] == "review",
             "default growth opportunity review package must require risk review")
    _require(package["readiness_status"] == "blocked",
             "default growth opportunity review package must be blocked")
    _require(package["review_recommendation"] == "do_not_execute",
             "blocked growth opportunity review package must recommend no execution")
    _require(package["blockers"], "growth opportunity review package must aggregate blockers")
    _require(package["warnings"], "growth opportunity review package must aggregate warnings")
    _require(package["required_human_actions"],
             "growth opportunity review package must aggregate required human actions")
    _require(any(item.startswith("missing evidence:") for item in package["blockers"]),
             "growth opportunity review package blockers must include missing evidence")
    _require(any(item.startswith("blocked action until evidence review:") for item in package["blockers"]),
             "growth opportunity review package blockers must include blocked actions")
    _require(any(item.startswith("risk review required:") for item in package["warnings"]),
             "growth opportunity review package warnings must include risk review items")
    _require(package["dry_run"] is True and package["write_allowed"] is False,
             "growth opportunity review package must be read-only")
    _require(package["automation_allowed"] is False and package["writes"] == [],
             "growth opportunity review package must not allow automation or writes")

    decoded = parse_growth_opportunity_review_package_json(stable_growth_opportunity_review_package_json(package))
    _require(decoded == package, "growth opportunity review package JSON must round trip")
    _require(stable_growth_opportunity_review_package_json(package) == stable_growth_opportunity_review_package_json(package),
             "growth opportunity review package JSON must be stable")

    bad_scan = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_scan["growth_business_opportunity_scan_id"] = "growth-business-opportunity-scan-wrong"
    try:
        validate_growth_opportunity_review_package(bad_scan, scan, contract)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject scan id mismatch")

    bad_contract = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_contract["growth_business_evidence_contract_id"] = "growth-business-evidence-contract-wrong"
    try:
        validate_growth_opportunity_review_package(bad_contract, scan, contract)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject evidence contract id mismatch")

    bad_status = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_status["opportunity_status"] = "maybe"
    try:
        validate_growth_opportunity_review_package(bad_status)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject invalid opportunity status")

    bad_evidence = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_evidence["evidence_status"] = "maybe"
    try:
        validate_growth_opportunity_review_package(bad_evidence)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject invalid evidence status")

    bad_approval = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_approval["approval_status"] = "review"
    bad_approval["required_human_actions"] = []
    try:
        validate_growth_opportunity_review_package(bad_approval)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject approval review without actions")

    bad_risk = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_risk["risk_status"] = "review"
    bad_risk["warnings"] = []
    try:
        validate_growth_opportunity_review_package(bad_risk)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject risk review without warnings")

    bad_readiness = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_readiness["readiness_status"] = "ready_for_review"
    try:
        validate_growth_opportunity_review_package(bad_readiness)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject ready status with blockers")

    bad_recommendation = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_recommendation["review_recommendation"] = "ready_for_review"
    try:
        validate_growth_opportunity_review_package(bad_recommendation)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject ready recommendation when blocked")

    bad_safety = json.loads(stable_growth_opportunity_review_package_json(package))
    bad_safety["write_allowed"] = True
    try:
        validate_growth_opportunity_review_package(bad_safety)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject unsafe safety metadata")

    missing = json.loads(stable_growth_opportunity_review_package_json(package))
    missing.pop("growth_opportunity_review_package_id")
    try:
        validate_growth_opportunity_review_package(missing)
    except ValueError:
        pass
    else:
        raise AssertionError("growth opportunity review validation must reject missing required fields")

    print("growth opportunity review package helper OK")


# ---------------------------------------------------------------------------
# Link-level research target intake and evidence bundle
# ---------------------------------------------------------------------------

def _research_target_test_paths() -> tuple[str, str, str]:
    zip_source = make_crawler_like_fixture()
    folder_source = "research/_extracted/sota-scan-master/sota-scan-master"
    file_source = "research/hermes_upgrade_actionable_shortlist.md"
    for source in (zip_source, folder_source, file_source):
        _require((ROOT / source).exists(), f"research target test fixture must exist: {source}")
    return zip_source, folder_source, file_source


def check_research_target_intake_helpers() -> None:
    from link_modes.growth.link_growth_console import (
        collect_research_target_evidence_bundle,
        collect_research_target_intake,
        collect_research_target_operator_flow,
        collect_research_target_operator_task_draft,
        collect_research_target_upgrade_candidates,
        parse_research_target_evidence_bundle_json,
        parse_research_target_intake_json,
        parse_research_target_operator_flow_json,
        parse_research_target_operator_task_draft_json,
        parse_research_target_upgrade_candidates_json,
        stable_research_target_evidence_bundle_json,
        stable_research_target_intake_json,
        stable_research_target_operator_flow_json,
        stable_research_target_operator_task_draft_json,
        stable_research_target_upgrade_candidates_json,
        validate_research_target_evidence_bundle,
        validate_research_target_intake,
        validate_research_target_operator_flow,
        validate_research_target_operator_task_draft,
        validate_research_target_upgrade_candidates,
    )

    zip_source, folder_source, file_source = _research_target_test_paths()
    zip_intake = collect_research_target_intake(zip_source)
    same_zip_intake = collect_research_target_intake(zip_source)
    _require(zip_intake["research_target_intake_id"] == same_zip_intake["research_target_intake_id"],
             "research target intake id must be deterministic")
    _require(zip_intake["source_type"] == "zip_archive", "zip source intake must detect zip_archive")
    _require(zip_intake["source_path"] == zip_source, "zip source path must be preserved")
    _require(zip_intake["archive_member_refs"], "zip intake must inspect archive members without extraction")
    _require(zip_intake["selected_file_refs"], "zip intake must include selected refs")
    zip_ref = zip_intake["selected_file_refs"][0]
    _require("!" in zip_ref["provenance_path"], "zip selected refs must include archive-qualified provenance_path")
    _require(zip_ref["provenance_path"].startswith(zip_source + "!"), "zip provenance_path must preserve archive source path")
    _require("!" not in zip_ref["display_path"] and not zip_ref["display_path"].startswith("research/"),
             "zip display_path must remain a clean archive member path")
    _require(zip_intake["dry_run"] is True and zip_intake["write_allowed"] is False,
             "research target intake must be read-only")
    _require(parse_research_target_intake_json(stable_research_target_intake_json(zip_intake)) == zip_intake,
             "research target intake JSON must round trip")

    folder_intake = collect_research_target_intake(folder_source)
    _require(folder_intake["source_type"] == "folder", "folder source intake must detect folder")
    _require(folder_intake["selected_file_refs"], "folder intake must include selected refs")
    _require(folder_intake["allowed_root"] == "research/_extracted", "folder intake must use most specific allowed root")
    folder_ref = folder_intake["selected_file_refs"][0]
    _require(folder_ref["display_path"] == folder_ref["provenance_path"],
             "folder refs must use the same display and provenance path")

    file_intake = collect_research_target_intake(file_source)
    _require(file_intake["source_type"] == "file", "file source intake must detect file")
    _require(file_intake["file_count"] == 1, "file intake must count one file")
    _require(file_intake["selected_file_refs"][0]["path"] == file_source,
             "file intake selected ref must preserve selected source")
    _require(file_intake["selected_file_refs"][0]["display_path"] == file_source,
             "file intake display path must preserve selected source")
    _require(file_intake["selected_file_refs"][0]["provenance_path"] == file_source,
             "file intake provenance path must preserve selected source")

    try:
        collect_research_target_intake("link.py")
    except ValueError:
        pass
    else:
        raise AssertionError("research target intake must reject paths outside research")

    evidence = collect_research_target_evidence_bundle(zip_intake)
    _require(evidence["research_target_intake_id"] == zip_intake["research_target_intake_id"],
             "research target evidence bundle must flow from intake")
    _require(evidence["source_refs"] and evidence["evidence_refs"],
             "research target evidence bundle must include source and evidence refs")
    _require("!" in evidence["source_refs"][0]["provenance_path"],
             "research target evidence source refs must preserve zip provenance")
    _require("!" in evidence["evidence_refs"][0]["provenance_path"],
             "research target evidence refs must preserve zip provenance")
    _require(evidence["provenance_summary"]["source_path"] == zip_source,
             "research target evidence provenance must include selected source")
    validate_research_target_evidence_bundle(evidence, zip_intake)
    _require(parse_research_target_evidence_bundle_json(stable_research_target_evidence_bundle_json(evidence)) == evidence,
             "research target evidence bundle JSON must round trip")

    candidates = collect_research_target_upgrade_candidates(zip_intake, evidence)
    _require(candidates["research_target_intake_id"] == zip_intake["research_target_intake_id"],
             "research target candidates must flow from intake")
    _require(candidates["research_target_evidence_bundle_id"] == evidence["research_target_evidence_bundle_id"],
             "research target candidates must flow from evidence bundle")
    _require(candidates["upgrade_candidates"], "research target upgrade candidates must be generated")
    candidate = candidates["upgrade_candidates"][0]
    _require(candidate["source_refs"] and candidate["evidence_refs"],
             "research target candidate must cite source and evidence refs")
    _require("copy external code" in candidate["blocked_actions"],
             "research target candidate must block copying external code")
    validate_research_target_upgrade_candidates(candidates, zip_intake, evidence)
    _require(parse_research_target_upgrade_candidates_json(stable_research_target_upgrade_candidates_json(candidates)) == candidates,
             "research target candidates JSON must round trip")

    task = collect_research_target_operator_task_draft(candidates, evidence)
    _require(task["research_target_intake_id"] == zip_intake["research_target_intake_id"],
             "research target task draft must flow from intake")
    _require(task["selected_upgrade_candidate_id"] in [item["upgrade_candidate_id"] for item in candidates["upgrade_candidates"]],
             "research target task draft must select a generated candidate")
    _require(zip_source in task["objective"] and zip_source in task["scope_summary"],
             "research target task draft must reference the selected source")
    _require(task["execution_allowed"] is False, "research target task draft must not allow execution")
    _require(task["likely_affected_files"] and task["expected_tests"] and task["rollback_plan"],
             "research target task draft must include files, tests, and rollback plan")
    validate_research_target_operator_task_draft(task, candidates, evidence)
    _require(parse_research_target_operator_task_draft_json(stable_research_target_operator_task_draft_json(task)) == task,
             "research target task draft JSON must round trip")

    flow = collect_research_target_operator_flow(source_path=zip_source)
    _require(flow["research_target_intake_id"] == zip_intake["research_target_intake_id"],
             "research target flow must include intake id")
    _require(flow["research_target_evidence_bundle_id"] == evidence["research_target_evidence_bundle_id"],
             "research target flow must include evidence id")
    _require(flow["research_target_upgrade_candidates_id"] == candidates["research_target_upgrade_candidates_id"],
             "research target flow must include candidate id")
    _require(flow["research_target_operator_task_draft_id"] == task["research_target_operator_task_draft_id"],
             "research target flow must include task id")
    _require(flow["selected_upgrade_summary"]["source_path"] == zip_source,
             "research target flow must reference selected source")
    validate_research_target_operator_flow(flow, zip_intake, evidence, candidates, task)
    _require(parse_research_target_operator_flow_json(stable_research_target_operator_flow_json(flow)) == flow,
             "research target operator flow JSON must round trip")

    bad_task = json.loads(stable_research_target_operator_task_draft_json(task))
    bad_task["execution_allowed"] = True
    try:
        validate_research_target_operator_task_draft(bad_task)
    except ValueError:
        pass
    else:
        raise AssertionError("research target task draft validation must reject execution_allowed=True")

    bad_intake = json.loads(stable_research_target_intake_json(zip_intake))
    bad_intake["allowed_root"] = ".agents"
    try:
        validate_research_target_intake(bad_intake)
    except ValueError:
        pass
    else:
        raise AssertionError("research target intake validation must reject invalid allowed_root")

    print("research target intake helpers OK")


def check_research_target_clis() -> None:
    from link import _cmd_research
    from link_modes.growth.link_growth_console import (
        parse_research_target_evidence_bundle_json,
        parse_research_target_intake_json,
        parse_research_target_operator_flow_json,
        parse_research_target_operator_task_draft_json,
        parse_research_target_upgrade_candidates_json,
    )

    zip_source, _, _ = _research_target_test_paths()
    help_out = io.StringIO()
    with contextlib.redirect_stdout(help_out):
        help_rc = _cmd_research(["--help"])
    _require(help_rc == 0, "research --help must return 0")
    for command in ("target-intake", "target-evidence", "target-upgrades", "target-task-draft", "target-flow"):
        _require(command in help_out.getvalue(), f"research help must include {command}")

    commands = [
        ("target-intake", parse_research_target_intake_json, "research_target_intake_id"),
        ("target-evidence", parse_research_target_evidence_bundle_json, "research_target_evidence_bundle_id"),
        ("target-upgrades", parse_research_target_upgrade_candidates_json, "research_target_upgrade_candidates_id"),
        ("target-task-draft", parse_research_target_operator_task_draft_json, "research_target_operator_task_draft_id"),
        ("target-flow", parse_research_target_operator_flow_json, "research_target_operator_flow_id"),
    ]
    for command, parser, id_key in commands:
        json_out = io.StringIO()
        with contextlib.redirect_stdout(json_out):
            json_rc = _cmd_research([command, "--source", zip_source, "--json"])
        _require(json_rc == 0, f"research {command} --json must return 0")
        payload = parser(json_out.getvalue())
        _require(id_key in payload, f"research {command} JSON must include id")
        _require(payload["dry_run"] is True and payload["write_allowed"] is False,
                 f"research {command} must remain read-only")
        _require(payload["automation_allowed"] is False and payload["writes"] == [],
                 f"research {command} must not allow automation or writes")
        if command == "target-task-draft":
            _require(zip_source in payload["objective"], "research target-task-draft must reference selected source")
        if command == "target-flow":
            _require(payload["selected_upgrade_summary"]["source_path"] == zip_source,
                     "research target-flow must reference selected source")
        human_out = io.StringIO()
        with contextlib.redirect_stdout(human_out):
            human_rc = _cmd_research([command, "--source", zip_source])
        _require(human_rc == 0, f"research {command} human mode must return 0")
        _require(len(human_out.getvalue().splitlines()) <= 10,
                 f"research {command} human mode must stay concise")
        write_out = io.StringIO()
        write_err = io.StringIO()
        with contextlib.redirect_stdout(write_out), contextlib.redirect_stderr(write_err):
            write_rc = _cmd_research([command, "--source", zip_source, "--write"])
        _require(write_rc != 0, f"research {command} --write must be rejected")
        _require("read-only" in write_err.getvalue(), f"research {command} --write must print clear error")
        _require(write_out.getvalue() == "", f"research {command} --write must not print normal output")
        missing_out = io.StringIO()
        missing_err = io.StringIO()
        with contextlib.redirect_stdout(missing_out), contextlib.redirect_stderr(missing_err):
            missing_rc = _cmd_research([command, "--json"])
        _require(missing_rc != 0, f"research {command} missing --source must be rejected")
        _require("requires --source" in missing_err.getvalue(),
                 f"research {command} missing --source must print clear error")

    outside_err = io.StringIO()
    with contextlib.redirect_stderr(outside_err):
        outside_rc = _cmd_research(["target-intake", "--source", "link.py", "--json"])
    _require(outside_rc != 0, "research target-intake must reject source outside research")
    _require("research" in outside_err.getvalue(), "outside-source rejection must mention research")

    print("research target CLIs OK")


def check_source_aware_downstream_binding_helpers() -> None:
    from link_modes.growth.link_growth_console import (
        build_source_aware_context_for_cli,
        collect_growth_business_evidence_contract,
        collect_growth_business_opportunity_scan,
        collect_growth_opportunity_review_package,
        collect_research_source_binding_context,
        collect_source_aware_operator_flow,
        parse_research_source_binding_context_json,
        parse_source_aware_operator_flow_json,
        stable_research_source_binding_context_json,
        stable_source_aware_operator_flow_json,
        validate_growth_business_evidence_contract,
        validate_growth_business_opportunity_scan,
        validate_growth_opportunity_review_package,
        validate_research_source_binding_context,
        validate_source_aware_operator_flow,
        validate_source_aware_provenance,
    )

    zip_source, _, _ = _research_target_test_paths()
    binding = collect_research_source_binding_context(source_path=zip_source)
    same_binding = collect_research_source_binding_context(source_path=zip_source)
    _require(binding["research_source_binding_context_id"] == same_binding["research_source_binding_context_id"],
             "research source binding id must be deterministic")
    _require(binding["source_path"] == zip_source, "research source binding must preserve source path")
    _require(binding["source_refs"] and binding["evidence_refs"] and binding["upgrade_candidate_refs"],
             "research source binding must include source, evidence, and upgrade refs")
    _require(all("!" in item for item in binding["source_refs"]),
             "research source binding zip refs must be archive-qualified")
    _require(binding["selected_upgrade_candidate_id"] in binding["upgrade_candidate_refs"],
             "research source binding selected candidate must be available")
    validate_research_source_binding_context(binding)
    _require(parse_research_source_binding_context_json(stable_research_source_binding_context_json(binding)) == binding,
             "research source binding JSON must round trip")

    scan = collect_growth_business_opportunity_scan(source_path=zip_source)
    validate_growth_business_opportunity_scan(scan)
    _require(scan["source_bound"] is True, "source-aware opportunity scan must be source-bound")
    _require(scan["source_path"] == zip_source and scan["source_name"] == Path(zip_source).name,
             "source-aware opportunity scan must include top-level source metadata")
    _require(scan["source_refs"] and all("!" in item for item in scan["source_refs"]),
             "source-aware opportunity scan must include archive-qualified source refs")
    _require(scan["research_target_intake_id"] == binding["research_target_intake_id"],
             "source-aware opportunity scan must include research target intake id")
    for opportunity in scan["opportunities"]:
        _require(opportunity["source_bound"] is True, "source-aware opportunities must be source-bound")
        _require(opportunity["research_target_intake_id"] == binding["research_target_intake_id"],
                 "source-aware opportunity must reference selected target")
        _require(opportunity["evidence_refs"], "source-aware opportunity must include evidence refs")
        _require(opportunity["source_path"] == zip_source, "source-aware opportunity must include source path")

    contract = collect_growth_business_evidence_contract(scan)
    validate_growth_business_evidence_contract(contract, scan)
    _require(contract["source_bound"] is True, "source-aware evidence contract must be source-bound")
    _require(contract["source_path"] == zip_source, "source-aware evidence contract must include source path")
    _require(contract["research_target_evidence_bundle_id"] == binding["research_target_evidence_bundle_id"],
             "source-aware evidence contract must include evidence bundle id")

    review = collect_growth_opportunity_review_package(scan, contract)
    validate_growth_opportunity_review_package(review, scan, contract)
    _require(review["source_bound"] is True, "source-aware opportunity review must be source-bound")
    _require(review["source_path"] == zip_source, "source-aware opportunity review must include source path")
    _require(review["research_target_intake_id"] == binding["research_target_intake_id"],
             "source-aware opportunity review must include selected target id")

    context = build_source_aware_context_for_cli(zip_source)
    _require(context["research_source_binding_context"]["research_source_binding_context_id"] == binding["research_source_binding_context_id"],
             "source-aware CLI context must preserve binding id")
    _require(context["operator_chain"]["task_draft"]["source_path"] == zip_source,
             "source-aware CLI context must build source-bound operator chain")

    import link_modes.growth.link_growth_console as growth_console
    original_intake = growth_console.collect_research_target_intake
    intake_calls = {"count": 0}

    def counted_intake(*args, **kwargs):
        intake_calls["count"] += 1
        return original_intake(*args, **kwargs)

    growth_console.collect_research_target_intake = counted_intake
    try:
        counted_context = growth_console.build_source_aware_context_for_cli(zip_source)
    finally:
        growth_console.collect_research_target_intake = original_intake
    _require(intake_calls["count"] == 1,
             "source-aware CLI context must not rebuild research target intake repeatedly")
    _require(counted_context["operator_chain"]["task_draft"]["source_path"] == zip_source,
             "source-aware context reuse guard must still build operator task draft")

    flow = collect_source_aware_operator_flow(source_path=zip_source, source_context=context)
    validate_source_aware_operator_flow(flow)
    _require(flow["research_target_intake_id"] == binding["research_target_intake_id"],
             "source-aware flow must include binding target id")
    _require(flow["source_bound"] is True, "source-aware flow must be source-bound")
    _require(flow["source_path"] == zip_source and flow["source_refs"],
             "source-aware flow must include top-level source provenance")
    _require(parse_source_aware_operator_flow_json(stable_source_aware_operator_flow_json(flow)) == flow,
             "source-aware operator flow JSON must round trip")

    bad_missing_source = dict(flow)
    bad_missing_source.pop("source_path")
    try:
        validate_source_aware_provenance(bad_missing_source)
    except ValueError:
        pass
    else:
        raise AssertionError("source-aware provenance validation must reject missing source_path")

    bad_refs = dict(flow)
    bad_refs["source_refs"] = []
    try:
        validate_source_aware_provenance(bad_refs)
    except ValueError:
        pass
    else:
        raise AssertionError("source-aware provenance validation must reject missing source_refs")

    bad_zip = dict(flow)
    bad_zip["source_refs"] = ["gpt-crawler-main/README.md"]
    try:
        validate_source_aware_provenance(bad_zip)
    except ValueError:
        pass
    else:
        raise AssertionError("source-aware provenance validation must reject unqualified zip provenance")

    bad_safety = dict(flow)
    bad_safety["write_allowed"] = True
    try:
        validate_source_aware_provenance(bad_safety)
    except ValueError:
        pass
    else:
        raise AssertionError("source-aware provenance validation must reject unsafe writes")

    print("source-aware downstream binding helpers OK")


def check_source_aware_downstream_binding_clis() -> None:
    from link import _cmd_decision, _cmd_growth, _cmd_operator, _cmd_research
    from link_modes.growth.link_growth_console import (
        parse_decision_candidate_set_json,
        parse_decision_ranking_json,
        parse_growth_business_evidence_contract_json,
        parse_growth_business_opportunity_scan_json,
        parse_growth_opportunity_review_package_json,
        parse_operator_action_plan_preview_json,
        parse_operator_decision_review_json,
        parse_operator_decision_trace_package_json,
        parse_operator_task_draft_json,
        parse_operator_task_review_package_json,
        parse_research_source_binding_context_json,
        parse_source_aware_operator_flow_json,
    )

    zip_source, _, _ = _research_target_test_paths()
    research_commands = [
        ("source-binding", parse_research_source_binding_context_json, "research_source_binding_context_id"),
        ("source-operator-flow", parse_source_aware_operator_flow_json, "source_aware_operator_flow_id"),
    ]
    for command, parser, id_key in research_commands:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_research([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"research {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"research {command} must output only its payload")
        _require(payload["source_path"] == zip_source, f"research {command} must include top-level source_path")
        _require(payload["source_refs"], f"research {command} must include source refs")
        _require(payload["dry_run"] is True and payload["write_allowed"] is False,
                 f"research {command} must be read-only")
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_research([command, "--source", zip_source, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"research {command} --write must be rejected")

    growth_commands = [
        ("business-opportunities", parse_growth_business_opportunity_scan_json, "growth_business_opportunity_scan_id"),
        ("business-evidence-contract", parse_growth_business_evidence_contract_json, "growth_business_evidence_contract_id"),
        ("opportunity-review", parse_growth_opportunity_review_package_json, "growth_opportunity_review_package_id"),
    ]
    for command, parser, id_key in growth_commands:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_growth([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"growth {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"growth {command} must output only its payload")
        _require(payload["source_bound"] is True, f"growth {command} must be source-bound")
        _require(payload["source_path"] == zip_source, f"growth {command} must include top-level source_path")
        _require(payload["source_refs"] and payload["evidence_refs"], f"growth {command} must include source and evidence refs")
        _require(payload["research_target_intake_id"].startswith("research-target-intake-"),
                 f"growth {command} must include research target id")

    decision_commands = [
        ("candidates", parse_decision_candidate_set_json, "decision_candidate_set_id"),
        ("ranking", parse_decision_ranking_json, "decision_ranking_id"),
        ("review", parse_operator_decision_review_json, "operator_decision_review_id"),
        ("trace", parse_operator_decision_trace_package_json, "operator_decision_trace_package_id"),
    ]
    for command, parser, id_key in decision_commands:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_decision([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"decision {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"decision {command} must output only its payload")
        _require(payload["source_bound"] is True, f"decision {command} must be source-bound")
        _require(payload["source_path"] == zip_source, f"decision {command} must include top-level source_path")
        _require(payload["source_refs"] and payload["evidence_refs"], f"decision {command} must include source and evidence refs")
        if command == "candidates":
            top_ids = [item["decision_candidate_id"] for item in payload["candidates"]]
            _require(top_ids, "source-aware decision candidates must include candidate ids")
        if command == "ranking":
            ranked_ids = [item["decision_candidate_id"] for item in payload["ranked_candidates"]]
            _require(payload["top_candidate_id"] in ranked_ids,
                     "source-aware decision ranking top candidate must be ranked")

    operator_commands = [
        ("action-plan", parse_operator_action_plan_preview_json, "operator_action_plan_preview_id"),
        ("action-review", parse_operator_task_review_package_json, "operator_action_review_package_id"),
        ("task-draft", parse_operator_task_draft_json, "operator_task_draft_id"),
        ("task-review", parse_operator_task_review_package_json, "operator_task_review_package_id"),
    ]
    # action-review has its own parser; keep the table compact by fixing it here.
    operator_commands[1] = ("action-review", __import__("link_modes.growth.link_growth_console", fromlist=["parse_operator_action_review_package_json"]).parse_operator_action_review_package_json, "operator_action_review_package_id")
    for command, parser, id_key in operator_commands:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_operator([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"operator {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"operator {command} must output only its payload")
        _require(payload["source_bound"] is True, f"operator {command} must be source-bound")
        _require(payload["source_path"] == zip_source, f"operator {command} must include top-level source_path")
        _require(payload["source_refs"] and payload["evidence_refs"], f"operator {command} must include source and evidence refs")
        if command == "task-draft":
            _require(payload["source_path"] == zip_source and payload["source_name"] == Path(zip_source).name,
                     "source-aware operator task draft must reference selected source")
            _require(payload["execution_allowed"] is False,
                     "source-aware operator task draft must remain non-executable")

    print("source-aware downstream binding CLIs OK")


def check_source_aware_operator_report_and_sandbox_helpers() -> None:
    from link_modes.growth.link_growth_console import (
        build_source_aware_sandbox_context_for_cli,
        collect_research_target_implementation_preview,
        collect_research_target_operator_report,
        collect_research_target_sandbox_flow,
        parse_research_target_implementation_preview_json,
        parse_research_target_operator_report_json,
        parse_research_target_sandbox_flow_json,
        stable_research_target_implementation_preview_json,
        stable_research_target_operator_report_json,
        stable_research_target_sandbox_flow_json,
        validate_research_target_implementation_preview,
        validate_research_target_operator_report,
        validate_research_target_sandbox_flow,
        validate_sandbox_execution_approval_checklist,
        validate_sandbox_execution_evidence_contract,
        validate_sandbox_execution_review_package,
        validate_sandbox_task_executor_boundary,
    )

    zip_source, _, _ = _research_target_test_paths()
    report = collect_research_target_operator_report(source_path=zip_source)
    same_report = collect_research_target_operator_report(source_path=zip_source)
    _require(report["research_target_operator_report_id"] == same_report["research_target_operator_report_id"],
             "research target operator report id must be deterministic")
    _require(report["source_path"] == zip_source, "operator report must include source_path")
    _require(report["source_bound"] is True, "operator report must be source-bound")
    _require(report["selected_upgrade_title"], "operator report must include selected upgrade title")
    _require(report["target_link_module"] in {"engineering", "growth", "business_development", "business_operations", "shared_services", "control_plane", "research", "unknown"},
             "operator report must include target Link module")
    _require(report["source_refs_summary"] and report["evidence_refs_summary"],
             "operator report must include source/evidence summaries")
    _require(all("!" in item["provenance_path"] for item in report["source_refs_summary"]),
             "operator report zip source summaries must be archive-qualified")
    _require(report["likely_affected_files"], "operator report must include likely affected files")
    _require(zip_source in report["task_draft_summary"]["objective"],
             "operator report task summary must reference selected source")
    validate_research_target_operator_report(report)
    _require(parse_research_target_operator_report_json(stable_research_target_operator_report_json(report)) == report,
             "operator report JSON must round trip")

    preview = collect_research_target_implementation_preview(source_path=zip_source, operator_report=report)
    same_preview = collect_research_target_implementation_preview(source_path=zip_source, operator_report=report)
    _require(preview["research_target_implementation_preview_id"] == same_preview["research_target_implementation_preview_id"],
             "implementation preview id must be deterministic")
    _require(preview["research_target_operator_report_id"] == report["research_target_operator_report_id"],
             "implementation preview must flow from report")
    _require(preview["selected_upgrade_candidate_id"] == report["selected_upgrade_candidate_id"],
             "implementation preview must preserve selected candidate")
    _require(preview["likely_affected_files"] and preview["allowed_file_scope"],
             "implementation preview must include affected/allowed files")
    _require(preview["acceptance_criteria"], "implementation preview must include acceptance criteria")
    _require(preview["execution_allowed"] is False, "implementation preview must be non-executable")
    _require(zip_source in preview["objective"] or zip_source in preview["implementation_scope"],
             "implementation preview must reference selected source")
    validate_research_target_implementation_preview(preview, report)
    _require(parse_research_target_implementation_preview_json(stable_research_target_implementation_preview_json(preview)) == preview,
             "implementation preview JSON must round trip")

    context = build_source_aware_sandbox_context_for_cli(zip_source)
    for key in ("boundary", "evidence", "approvals", "review"):
        payload = context[key]
        _require(payload["source_bound"] is True, f"source-aware sandbox {key} must be source-bound")
        _require(payload["source_path"] == zip_source, f"source-aware sandbox {key} must include selected source")
        _require(payload["research_target_intake_id"] == report["research_target_intake_id"],
                 f"source-aware sandbox {key} must preserve target id")
        _require(payload["research_target_implementation_preview_id"] == preview["research_target_implementation_preview_id"],
                 f"source-aware sandbox {key} must preserve implementation preview id")
    validate_sandbox_task_executor_boundary(context["boundary"])
    validate_sandbox_execution_evidence_contract(context["evidence"], context["boundary"])
    validate_sandbox_execution_approval_checklist(context["approvals"], context["boundary"])
    validate_sandbox_execution_review_package(context["review"], context["boundary"], context["evidence"], context["approvals"], context["task_review"])

    flow = collect_research_target_sandbox_flow(source_path=zip_source, sandbox_context=context)
    _require(flow["research_target_operator_report_id"] == report["research_target_operator_report_id"],
             "sandbox flow must include report id")
    _require(flow["research_target_implementation_preview_id"] == preview["research_target_implementation_preview_id"],
             "sandbox flow must include implementation preview id")
    _require(flow["sandbox_task_executor_boundary_id"] == context["boundary"]["sandbox_task_executor_boundary_id"],
             "sandbox flow must include boundary id")
    _require(flow["sandbox_execution_review_package_id"] == context["review"]["sandbox_execution_review_package_id"],
             "sandbox flow must include sandbox review id")
    _require(flow["execution_candidate_status"] == "blocked", "sandbox flow must remain blocked")
    validate_research_target_sandbox_flow(flow)
    _require(parse_research_target_sandbox_flow_json(stable_research_target_sandbox_flow_json(flow)) == flow,
             "sandbox flow JSON must round trip")

    bad_report = json.loads(stable_research_target_operator_report_json(report))
    bad_report["source_refs_summary"][0]["provenance_path"] = bad_report["source_refs_summary"][0]["display_path"]
    try:
        validate_research_target_operator_report(bad_report)
    except ValueError:
        pass
    else:
        raise AssertionError("operator report validation must reject unqualified zip provenance")

    bad_preview = json.loads(stable_research_target_implementation_preview_json(preview))
    bad_preview["execution_allowed"] = True
    try:
        validate_research_target_implementation_preview(bad_preview)
    except ValueError:
        pass
    else:
        raise AssertionError("implementation preview validation must reject execution_allowed=True")

    print("source-aware operator report and sandbox helpers OK")


def check_source_aware_operator_report_and_sandbox_clis() -> None:
    from link import _cmd_research, _cmd_sandbox_executor
    from link_modes.growth.link_growth_console import (
        parse_research_target_implementation_preview_json,
        parse_research_target_operator_report_json,
        parse_research_target_sandbox_flow_json,
        parse_sandbox_execution_approval_checklist_json,
        parse_sandbox_execution_evidence_contract_json,
        parse_sandbox_execution_review_package_json,
        parse_sandbox_task_executor_boundary_json,
    )

    zip_source, _, _ = _research_target_test_paths()
    research_commands = [
        ("target-operator-report", parse_research_target_operator_report_json, "research_target_operator_report_id"),
        ("target-implementation-preview", parse_research_target_implementation_preview_json, "research_target_implementation_preview_id"),
        ("target-sandbox-flow", parse_research_target_sandbox_flow_json, "research_target_sandbox_flow_id"),
    ]
    for command, parser, id_key in research_commands:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_research([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"research {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"research {command} must output only its payload")
        _require(payload["source_bound"] is True and payload["source_path"] == zip_source,
                 f"research {command} must be source-bound")
        _require(payload["write_allowed"] is False and payload["automation_allowed"] is False and payload["writes"] == [],
                 f"research {command} must remain read-only")
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_research([command, "--source", zip_source, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"research {command} --write must be rejected")
        missing_err = io.StringIO()
        with contextlib.redirect_stderr(missing_err):
            missing_rc = _cmd_research([command, "--json"])
        _require(missing_rc != 0 and "requires --source" in missing_err.getvalue(),
                 f"research {command} missing --source must be rejected")
        outside_err = io.StringIO()
        with contextlib.redirect_stderr(outside_err):
            outside_rc = _cmd_research([command, "--source", "../README.md", "--json"])
        _require(outside_rc != 0, f"research {command} outside source must be rejected")

    sandbox_commands = [
        ("boundary", parse_sandbox_task_executor_boundary_json, "sandbox_task_executor_boundary_id"),
        ("evidence", parse_sandbox_execution_evidence_contract_json, "sandbox_execution_evidence_contract_id"),
        ("approvals", parse_sandbox_execution_approval_checklist_json, "sandbox_execution_approval_checklist_id"),
        ("review", parse_sandbox_execution_review_package_json, "sandbox_execution_review_package_id"),
    ]
    for command, parser, id_key in sandbox_commands:
        no_source_out = io.StringIO()
        with contextlib.redirect_stdout(no_source_out):
            no_source_rc = _cmd_sandbox_executor([command, "--json"])
        _require(no_source_rc == 0, f"sandbox-executor {command} no-source must still return 0")
        no_source_payload = parser(no_source_out.getvalue())
        _require(id_key in no_source_payload, f"sandbox-executor {command} no-source payload must validate")

        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_sandbox_executor([command, "--source", zip_source, "--json"])
        _require(rc == 0, f"sandbox-executor {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"sandbox-executor {command} must output only its payload")
        _require(payload["source_bound"] is True and payload["source_path"] == zip_source,
                 f"sandbox-executor {command} must be source-bound")
        _require(payload["research_target_intake_id"].startswith("research-target-intake-"),
                 f"sandbox-executor {command} must include research target id")
        _require(payload["research_target_implementation_preview_id"].startswith("research-target-implementation-preview-"),
                 f"sandbox-executor {command} must include implementation preview id")
        _require(payload["operator_task_draft_id"].startswith("operator-task-draft-"),
                 f"sandbox-executor {command} must include operator task draft id")
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_sandbox_executor([command, "--source", zip_source, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"sandbox-executor {command} --write must be rejected")

    print("source-aware operator report and sandbox CLIs OK")


def check_source_aware_control_plane_dashboard_helpers() -> None:
    from link_modes.growth.link_growth_console import (
        build_source_aware_dashboard_context_for_cli,
        collect_control_plane_target_status,
        collect_operator_target_review,
        collect_source_aware_advisor_command_preview,
        collect_source_aware_advisor_provider_card,
        collect_source_aware_operator_dashboard,
        collect_source_aware_target_decision_card,
        collect_source_aware_target_status_card,
        parse_control_plane_target_status_json,
        parse_operator_target_review_json,
        parse_source_aware_advisor_command_preview_json,
        parse_source_aware_advisor_provider_card_json,
        parse_source_aware_operator_dashboard_json,
        parse_source_aware_target_decision_card_json,
        parse_source_aware_target_status_card_json,
        stable_control_plane_target_status_json,
        stable_operator_target_review_json,
        stable_source_aware_advisor_command_preview_json,
        stable_source_aware_advisor_provider_card_json,
        stable_source_aware_operator_dashboard_json,
        stable_source_aware_target_decision_card_json,
        stable_source_aware_target_status_card_json,
        validate_control_plane_target_status,
        validate_operator_target_review,
        validate_source_aware_advisor_command_preview,
        validate_source_aware_advisor_provider_card,
        validate_source_aware_operator_dashboard,
        validate_source_aware_target_decision_card,
        validate_source_aware_target_status_card,
    )

    zip_source, _, _ = _research_target_test_paths()
    context = build_source_aware_dashboard_context_for_cli(zip_source)
    advisor_card = collect_source_aware_advisor_provider_card(source_path=zip_source, dashboard_context=context)
    same_advisor_card = collect_source_aware_advisor_provider_card(source_path=zip_source, dashboard_context=context)
    _require(advisor_card["source_aware_advisor_provider_card_id"] == same_advisor_card["source_aware_advisor_provider_card_id"],
             "source-aware advisor provider card id must be deterministic")
    _require(advisor_card["source_path"] == zip_source and advisor_card["default_provider"] == "llamacpp",
             "source-aware advisor card must preserve source and local default")
    _require(advisor_card["fallback_allowed"] is False and advisor_card["openrouter_opt_in_required"] is True,
             "source-aware advisor card must block fallback and show OpenRouter explicit opt-in")
    _require(isinstance(advisor_card["openrouter_key_present"], bool),
             "source-aware advisor card must expose OpenRouter key presence as boolean only")
    validate_source_aware_advisor_provider_card(advisor_card)
    _require(parse_source_aware_advisor_provider_card_json(stable_source_aware_advisor_provider_card_json(advisor_card)) == advisor_card,
             "source-aware advisor provider card JSON must round trip")
    command_preview = collect_source_aware_advisor_command_preview(source_path=zip_source, dashboard_context=context, advisor_card=advisor_card)
    _require(zip_source in command_preview["deterministic_preview_command"] and zip_source in command_preview["local_advisor_command"],
             "advisor command preview must reference selected source")
    _require("micro-diagnostic" in command_preview["recommended_micro_diagnostic_command"] and len(command_preview["recommended_micro_stage_commands"]) == 4,
             "advisor command preview must include micro diagnostic and four micro stage commands")
    _require("compression-policy" in command_preview["compression_policy_command"] and "compression-preview" in command_preview["compression_preview_command"],
             "advisor command preview must include compression policy and preview commands")
    _require(command_preview["compression_enabled_by_default"] is False,
             "advisor command preview must keep compression disabled by default")
    _require("--provider openrouter" in command_preview["openrouter_advisor_command"] and command_preview["fallback_allowed"] is False,
             "advisor command preview must make OpenRouter explicit and block fallback")
    validate_source_aware_advisor_command_preview(command_preview)
    _require(parse_source_aware_advisor_command_preview_json(stable_source_aware_advisor_command_preview_json(command_preview)) == command_preview,
             "source-aware advisor command preview JSON must round trip")
    card = collect_source_aware_target_status_card(source_path=zip_source, dashboard_context=context)
    same_card = collect_source_aware_target_status_card(source_path=zip_source, dashboard_context=context)
    _require(card["source_aware_target_status_card_id"] == same_card["source_aware_target_status_card_id"],
             "source-aware target status card id must be deterministic")
    _require(card["source_bound"] is True and card["source_path"] == zip_source,
             "source-aware target status card must reference selected source")
    _require(card["selected_upgrade_candidate_id"], "target status card must include selected upgrade candidate")
    _require(card["source_refs_summary"] and card["evidence_refs_summary"],
             "target status card must include compact ref summaries")
    _require(all("!" in item["provenance_path"] for item in card["source_refs_summary"]),
             "target status card zip provenance must be archive-qualified")
    _require("research_target_operator_report" not in card and "operator_task_draft" not in card,
             "target status card must not embed full nested payloads")
    validate_source_aware_target_status_card(card)
    _require(parse_source_aware_target_status_card_json(stable_source_aware_target_status_card_json(card)) == card,
             "target status card JSON must round trip")

    control = collect_control_plane_target_status(source_path=zip_source, dashboard_context=context, status_card=card)
    _require(control["source_path"] == zip_source and control["source_bound"] is True,
             "control-plane target status must be source-bound")
    _require(control["source_aware_target_status_card_id"] == card["source_aware_target_status_card_id"],
             "control-plane target status must preserve status card id")
    _require(control["advisor_local_status"] and control["advisor_openrouter_status"],
             "control-plane target status must include advisor local/openrouter status")
    validate_control_plane_target_status(control, card)
    _require(parse_control_plane_target_status_json(stable_control_plane_target_status_json(control)) == control,
             "control-plane target status JSON must round trip")

    review = collect_operator_target_review(source_path=zip_source, dashboard_context=context, status_card=card)
    _require(review["source_path"] == zip_source and review["source_bound"] is True,
             "operator target review must be source-bound")
    _require(review["selected_upgrade_candidate_id"] == card["selected_upgrade_candidate_id"],
             "operator target review must preserve selected candidate")
    _require(review["likely_affected_files"] and review["expected_tests"],
             "operator target review must include affected files and expected tests")
    _require(review["execution_allowed"] is False,
             "operator target review must remain non-executable")
    validate_operator_target_review(review)
    _require(parse_operator_target_review_json(stable_operator_target_review_json(review)) == review,
             "operator target review JSON must round trip")

    decision = collect_source_aware_target_decision_card(source_path=zip_source, dashboard_context=context)
    _require(decision["source_path"] == zip_source and decision["source_bound"] is True,
             "decision target card must be source-bound")
    _require(decision["selected_upgrade_candidate_id"] == card["selected_upgrade_candidate_id"],
             "decision target card must preserve selected candidate")
    _require(decision["top_candidate_id"] and decision["why_this_candidate"],
             "decision target card must explain the winning candidate")
    _require(decision["recommended_advisor_mode"],
             "decision target card must include advisor mode")
    _require(zip_source in decision["why_this_candidate"],
             "decision target card explanation must reference selected target")
    validate_source_aware_target_decision_card(decision)
    _require(parse_source_aware_target_decision_card_json(stable_source_aware_target_decision_card_json(decision)) == decision,
             "decision target card JSON must round trip")

    dashboard = collect_source_aware_operator_dashboard(source_path=zip_source, dashboard_context=context)
    same_dashboard = collect_source_aware_operator_dashboard(source_path=zip_source, dashboard_context=context)
    _require(dashboard["source_aware_operator_dashboard_id"] == same_dashboard["source_aware_operator_dashboard_id"],
             "source-aware operator dashboard id must be deterministic")
    _require(dashboard["source_path"] == zip_source and dashboard["source_bound"] is True,
             "source-aware operator dashboard must be source-bound")
    _require(dashboard["research_target_intake_id"] == card["research_target_intake_id"],
             "dashboard must preserve research target intake id")
    _require(dashboard["selected_upgrade_candidate_id"] == card["selected_upgrade_candidate_id"],
             "dashboard must preserve selected candidate")
    _require(dashboard["advisor_provider_card_id"] == advisor_card["source_aware_advisor_provider_card_id"],
             "dashboard must include source-aware advisor provider card id")
    _require(dashboard["recommended_advisor_command"] == advisor_card["recommended_advisor_command"],
             "dashboard must include recommended advisor command")
    _require(dashboard["advisor_fallback_allowed"] is False,
             "dashboard must block advisor fallback")
    _require(dashboard["source_aware_target_status_card_id"] == card["source_aware_target_status_card_id"],
             "dashboard must preserve status card id")
    _require(dashboard["control_plane_target_status_id"] == control["control_plane_target_status_id"],
             "dashboard must preserve control-plane target status id")
    _require(dashboard["operator_target_review_id"] == review["operator_target_review_id"],
             "dashboard must preserve operator target review id")
    _require(dashboard["source_aware_target_decision_card_id"] == decision["source_aware_target_decision_card_id"],
             "dashboard must preserve decision card id")
    _require(dashboard["key_findings"] and dashboard["next_actions"],
             "dashboard must include compact findings and next actions")
    _require("research_target_operator_report" not in dashboard and "operator_target_review" not in dashboard,
             "dashboard must not embed full nested payloads")
    validate_source_aware_operator_dashboard(dashboard)
    _require(parse_source_aware_operator_dashboard_json(stable_source_aware_operator_dashboard_json(dashboard)) == dashboard,
             "source-aware operator dashboard JSON must round trip")

    bad_dashboard = json.loads(stable_source_aware_operator_dashboard_json(dashboard))
    bad_dashboard["source_path"] = "research/other.zip"
    try:
        validate_source_aware_operator_dashboard(bad_dashboard)
    except ValueError:
        pass
    else:
        raise AssertionError("source-aware operator dashboard must reject mismatched source findings")

    print("source-aware control-plane dashboard helpers OK")


def check_source_aware_archive_concept_extractor_helpers() -> None:
    from link import _cmd_research
    from link_modes.growth.link_growth_console import (
        classify_repo_concept_family,
        collect_calibrated_repo_role_classification,
        collect_concept_confidence_calibration,
        collect_compression_aware_upgrade_scorer,
        collect_compression_repo_concept_profile,
        collect_growth_upgrade_genericity_assessment,
        collect_repo_role_calibration_fixtures,
        collect_repo_role_calibration_policy,
        collect_research_target_operator_task_draft,
        collect_research_target_recommendation_specificity,
        collect_research_target_upgrade_candidates,
        collect_research_target_upgrade_rationale_card,
        collect_source_aware_archive_concepts,
        build_source_aware_context_for_cli,
        parse_calibrated_repo_role_classification_json,
        parse_concept_confidence_calibration_json,
        parse_compression_aware_upgrade_scorer_json,
        parse_compression_repo_concept_profile_json,
        parse_growth_upgrade_genericity_assessment_json,
        parse_repo_role_calibration_fixtures_json,
        parse_repo_role_calibration_policy_json,
        parse_source_aware_archive_concepts_json,
        stable_calibrated_repo_role_classification_json,
        stable_concept_confidence_calibration_json,
        rank_detected_repo_concepts,
        score_archive_concept_signals,
        stable_compression_aware_upgrade_scorer_json,
        stable_compression_repo_concept_profile_json,
        stable_growth_upgrade_genericity_assessment_json,
        stable_repo_role_calibration_fixtures_json,
        stable_repo_role_calibration_policy_json,
        stable_research_target_upgrade_candidates_json,
        stable_source_aware_archive_concepts_json,
        validate_calibrated_repo_role_classification,
        validate_concept_confidence_calibration,
        summarize_repo_role_from_concepts,
        validate_compression_aware_upgrade_scorer,
        validate_compression_repo_concept_profile,
        validate_growth_upgrade_genericity_assessment,
        validate_repo_role_calibration_fixtures,
        validate_repo_role_calibration_policy,
        validate_source_aware_archive_concepts,
    )

    real_headroom_source = "research/headroom-main.zip"
    real_crawler_source = "research/gpt-crawler-main.zip"
    real_agent_reach_source = "research/Agent-Reach-main.zip"
    headroom_source = make_headroom_like_fixture()
    crawler_source = make_crawler_like_fixture()
    agent_reach_source = make_reach_like_fixture()
    workflow_source = make_workflow_like_fixture()

    scored_signal = score_archive_concept_signals("headroom compression token reduction rag chunks", {
        "concept_id": "compression_library",
        "concept_family": "compression",
        "keywords": ("compression", "token reduction", "headroom"),
    })
    _require(scored_signal["score"] >= 75, "concept signal scoring must rank strong compression evidence high")
    _require(classify_repo_concept_family([scored_signal]) == ["compression"],
             "concept family classifier must be deterministic")

    headroom_concepts = collect_source_aware_archive_concepts(source_path=headroom_source)
    _require("compression" in headroom_concepts["concept_families"],
             "Headroom archive concepts must detect compression family")
    _require(any(item["concept_id"] in {"mcp_server", "proxy_mode", "library_api", "cli_mode"} for item in headroom_concepts["detected_concepts"]),
             "Headroom archive concepts must detect at least one interface mode")
    _require(headroom_concepts["fallback_allowed"] is False and headroom_concepts["source_refs"] and headroom_concepts["evidence_refs"],
             "archive concepts must preserve refs and disable fallback")
    _require(all({"evidence_id", "signal_type", "signal_value", "source_ref", "evidence_ref", "weight"}.issubset(item) for item in headroom_concepts["concept_evidence"]),
             "archive concept evidence must include structured signal provenance")
    _require(summarize_repo_role_from_concepts(headroom_concepts["concept_families"], headroom_concepts["detected_concepts"]).startswith("compression"),
             "repo role summary must be derived from concepts")
    _require(rank_detected_repo_concepts(headroom_concepts["detected_concepts"])[0]["confidence"] >= headroom_concepts["detected_concepts"][-1]["confidence"],
             "concept ranking must be deterministic by confidence")
    validate_source_aware_archive_concepts(headroom_concepts)
    _require(parse_source_aware_archive_concepts_json(stable_source_aware_archive_concepts_json(headroom_concepts)) == headroom_concepts,
             "archive concepts JSON must round trip")

    role_policy = collect_repo_role_calibration_policy()
    _require(any(item["role_family"] == "business_reach_outreach" for item in role_policy["role_families"]),
             "repo role policy must include business/reach role")
    _require(any(item["role_family"] == "crawler_source_collection" for item in role_policy["role_families"]),
             "repo role policy must include crawler/source collection role")
    _require(next(item for item in role_policy["role_families"] if item["role_family"] == "compression_context")["conflicting_role_families"],
             "compression role must include conflicting roles")
    validate_repo_role_calibration_policy(role_policy)
    _require(parse_repo_role_calibration_policy_json(stable_repo_role_calibration_policy_json(role_policy)) == role_policy,
             "repo role policy JSON must round trip")

    role_fixtures = collect_repo_role_calibration_fixtures()
    _require(next(item for item in role_fixtures["fixtures"] if item["source_path"] == real_headroom_source)["expected_primary_role"] == "compression_context",
             "Headroom fixture must expect compression role")
    _require(next(item for item in role_fixtures["fixtures"] if item["source_path"] == real_crawler_source)["expected_primary_role"] == "crawler_source_collection",
             "gpt-crawler fixture must expect crawler role")
    _require("compression_context" in next(item for item in role_fixtures["fixtures"] if item["source_path"] == real_agent_reach_source)["expected_negative_roles"],
             "Agent-Reach fixture must reject compression role")
    validate_repo_role_calibration_fixtures(role_fixtures)
    _require(parse_repo_role_calibration_fixtures_json(stable_repo_role_calibration_fixtures_json(role_fixtures)) == role_fixtures,
             "repo role fixtures JSON must round trip")

    headroom_role = collect_calibrated_repo_role_classification(headroom_concepts)
    _require(headroom_role["primary_role"] == "compression_context" and headroom_role["primary_role_confidence"] == "high",
             "Headroom calibrated role must be high-confidence compression_context")
    validate_calibrated_repo_role_classification(headroom_role, headroom_concepts)
    _require(parse_calibrated_repo_role_classification_json(stable_calibrated_repo_role_classification_json(headroom_role)) == headroom_role,
             "calibrated repo role JSON must round trip")

    headroom_confidence = collect_concept_confidence_calibration(headroom_concepts, headroom_role)
    _require(any(item["concept_family"] == "compression" and item["calibrated_confidence"] >= 55 for item in headroom_confidence["concept_calibrations"]),
             "Headroom compression concepts must stay medium/high after calibration")
    validate_concept_confidence_calibration(headroom_confidence, headroom_concepts, headroom_role)
    _require(parse_concept_confidence_calibration_json(stable_concept_confidence_calibration_json(headroom_confidence)) == headroom_confidence,
             "concept confidence JSON must round trip")

    profile = collect_compression_repo_concept_profile(headroom_concepts)
    _require(profile["is_compression_repo"] is True and profile["compression_score"] >= 45,
             "Headroom compression profile must identify compression repo")
    _require(profile["compression_profile_decision"] == "compression_repo" and profile["calibrated_compression_score"] >= profile["raw_compression_score"],
             "Headroom compression profile must expose calibrated compression decision")
    _require(profile["recommended_integration_mode"] == "preview_or_bounded_local_adapter",
             "Headroom profile must recommend preview/bounded local adapter")
    _require("mcp_server" in profile["interface_modes"] and "auto_mcp_server_start" in profile["unsafe_modes"],
             "Headroom profile must detect MCP but keep it unsafe by default")
    _require("source_refs" in profile["metadata_preservation_requirements"] and "alias_map" in profile["metadata_preservation_requirements"],
             "Headroom profile must preserve refs and alias map")
    validate_compression_repo_concept_profile(profile)
    _require(parse_compression_repo_concept_profile_json(stable_compression_repo_concept_profile_json(profile)) == profile,
             "compression profile JSON must round trip")

    upgrades = collect_research_target_upgrade_candidates(source_path=headroom_source)
    _require("compression" in upgrades["detected_concept_families"] and upgrades["recommended_concept_specific_upgrade"],
             "target-upgrades must include compression concept summary for Headroom")
    _require(upgrades["upgrade_candidates"][0]["compression_specific"] is True,
             "Headroom top upgrade candidate must be compression-specific")

    genericity = collect_growth_upgrade_genericity_assessment(headroom_concepts, upgrades)
    _require(genericity["concept_supported_upgrade_count"] >= 1 and genericity["fallback_allowed"] is False,
             "genericity assessment must identify concept-supported upgrades without fallback")
    synthetic_generic_upgrades = json.loads(stable_research_target_upgrade_candidates_json(upgrades))
    generic_candidate = dict(synthetic_generic_upgrades["upgrade_candidates"][0])
    generic_candidate["upgrade_candidate_id"] = "research-target-upgrade-candidate-generic0001"
    generic_candidate["title"] = "Add tests"
    generic_candidate["description"] = "Add tests for this target."
    generic_candidate.pop("uses_repo_concepts", None)
    generic_candidate.pop("compression_specific", None)
    synthetic_generic_upgrades["upgrade_candidates"] = [generic_candidate]
    generic_fixture = collect_growth_upgrade_genericity_assessment(headroom_concepts, synthetic_generic_upgrades)
    _require(generic_fixture["generic_upgrade_count"] == 1 and generic_fixture["rejected_generic_upgrades"],
             "genericity assessment must flag unsupported add-tests candidates")
    validate_growth_upgrade_genericity_assessment(genericity)
    _require(parse_growth_upgrade_genericity_assessment_json(stable_growth_upgrade_genericity_assessment_json(genericity)) == genericity,
             "genericity assessment JSON must round trip")

    scorer = collect_compression_aware_upgrade_scorer(headroom_concepts, profile, upgrades)
    _require(scorer["genericity_assessment_id"] == genericity["growth_upgrade_genericity_assessment_id"],
             "compression scorer must link to genericity assessment")
    _require(scorer["best_upgrade"]["compression_specific"] is True,
             "Headroom best scored upgrade must be compression-specific")
    _require("compression" in scorer["best_upgrade"]["upgrade_title"].lower(),
             "Headroom best scored upgrade title must be compression-specific")
    _require(scorer["rejected_generic_upgrades"],
             "Headroom scorer should down-rank generic upgrades")
    validate_compression_aware_upgrade_scorer(scorer)
    _require(parse_compression_aware_upgrade_scorer_json(stable_compression_aware_upgrade_scorer_json(scorer)) == scorer,
             "compression-aware scorer JSON must round trip")

    rationale = collect_research_target_upgrade_rationale_card(source_path=headroom_source)
    _require(rationale["recommended_concept_specific_upgrade"] == scorer["selected_upgrade_candidate_id"],
             "target-upgrade-rationale must mention concept-supported upgrade")
    specificity = collect_research_target_recommendation_specificity(source_path=headroom_source)
    _require(specificity["concept_specificity_score"] >= specificity["specificity_score"],
             "target-specificity must expose concept specificity score")
    draft = collect_research_target_operator_task_draft(source_path=headroom_source)
    _require(draft["concept_supported_task_steps"] and "compression" in " ".join(draft["concept_supported_task_steps"]).lower(),
             "Headroom task draft must include compression-specific task steps")

    crawler_concepts = collect_source_aware_archive_concepts(source_path=crawler_source)
    crawler_role = collect_calibrated_repo_role_classification(crawler_concepts)
    _require(crawler_role["primary_role"] == "crawler_source_collection",
             "gpt-crawler calibrated role must be crawler_source_collection")
    crawler_confidence = collect_concept_confidence_calibration(crawler_concepts, crawler_role)
    _require(not any(item["concept_family"] == "compression" and item["calibrated_confidence"] >= 55 for item in crawler_confidence["concept_calibrations"]),
             "gpt-crawler compression concepts must not remain high")
    crawler_profile = collect_compression_repo_concept_profile(crawler_concepts)
    crawler_scorer = collect_compression_aware_upgrade_scorer(crawler_concepts, crawler_profile)
    _require(crawler_profile["compression_profile_decision"] == "not_compression_repo" and crawler_profile["calibrated_compression_score"] < profile["calibrated_compression_score"],
             "gpt-crawler calibrated compression profile must be low")
    _require(crawler_profile["is_compression_repo"] is False or crawler_profile["compression_score"] < profile["compression_score"],
             "gpt-crawler must not score like Headroom as a compression repo")
    _require(crawler_scorer["compression_relevance_score"] < scorer["compression_relevance_score"],
             "gpt-crawler compression relevance must stay below Headroom")

    agent_reach_concepts = collect_source_aware_archive_concepts(source_path=agent_reach_source)
    agent_reach_role = collect_calibrated_repo_role_classification(agent_reach_concepts)
    _require(agent_reach_role["primary_role"] != "compression_context",
             "Agent-Reach calibrated role must not be compression_context")
    agent_reach_confidence = collect_concept_confidence_calibration(agent_reach_concepts, agent_reach_role)
    _require(not any(item["concept_family"] == "compression" and item["calibrated_confidence"] >= 55 for item in agent_reach_confidence["concept_calibrations"]),
             "Agent-Reach compression concepts must be downranked unless direct evidence exists")
    agent_reach_profile = collect_compression_repo_concept_profile(agent_reach_concepts)
    _require(agent_reach_profile["compression_profile_decision"] == "not_compression_repo",
             "Agent-Reach compression profile must reject compression false positive")
    agent_reach_calibrated_task = collect_research_target_operator_task_draft(source_path=agent_reach_source)
    agent_reach_operator_task = build_source_aware_context_for_cli(agent_reach_source)["operator_chain"]["task_draft"]
    _require(agent_reach_operator_task["selected_upgrade_candidate_id"] == agent_reach_calibrated_task["selected_upgrade_candidate_id"],
             "source-aware operator task draft must align with calibrated task candidate")
    _require(agent_reach_operator_task["calibrated_best_growth_opportunity"] == agent_reach_calibrated_task["calibrated_best_growth_opportunity"],
             "source-aware operator task draft must expose calibrated best opportunity")
    _require(agent_reach_operator_task["task_alignment_source"] in {"decision_ranking", "calibrated_task_candidate"},
             "source-aware operator task draft must record alignment source")

    workflow_concepts = collect_source_aware_archive_concepts(source_path=workflow_source)
    workflow_role = collect_calibrated_repo_role_classification(workflow_concepts)
    _require(workflow_role["primary_role"] in {"workflow_automation", "ai_workflow_builder"},
             "workflow-like fixture must classify as workflow/AI builder, not compression")
    workflow_profile = collect_compression_repo_concept_profile(workflow_concepts)
    _require(workflow_profile["compression_profile_decision"] == "not_compression_repo",
             "workflow-like fixture compression profile must reject compression false positive")

    for command, parser, id_key in (
        ("repo-role-policy", parse_repo_role_calibration_policy_json, "repo_role_calibration_policy_id"),
        ("repo-role-fixtures", parse_repo_role_calibration_fixtures_json, "repo_role_calibration_fixtures_id"),
    ):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_research([command, "--json"])
        _require(rc == 0, f"research {command} --json must return 0")
        payload = parser(out.getvalue())
        _require(id_key in payload, f"research {command} must output own payload")
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_research([command, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"research {command} --write must be rejected")

    for command, parser in (
        ("archive-concepts", parse_source_aware_archive_concepts_json),
        ("repo-role", parse_calibrated_repo_role_classification_json),
        ("concept-confidence", parse_concept_confidence_calibration_json),
        ("compression-profile", parse_compression_repo_concept_profile_json),
        ("compression-upgrade-score", parse_compression_aware_upgrade_scorer_json),
        ("upgrade-genericity", parse_growth_upgrade_genericity_assessment_json),
    ):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = _cmd_research([command, "--source", headroom_source, "--json"])
        _require(rc == 0, f"research {command} --source --json must return 0")
        payload = parser(out.getvalue())
        _require(payload["source_path"] == headroom_source, f"research {command} must preserve source path")
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_research([command, "--source", headroom_source, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"research {command} --write must be rejected")

    print("source-aware archive concept extractor helpers OK")


