    with contextlib.redirect_stdout(two_stage_out):
        two_stage_rc = _cmd_research(["advisor-two-stage", "--source", zip_source, "--json"])
    _require(two_stage_rc == 0, "research advisor-two-stage preview --json must return 0")
    two_stage = parse_two_stage_local_advisor_gate_json(two_stage_out.getvalue())
    _require(two_stage["stage1_passed"] is False and two_stage["stage2_attempted"] is False,
             "advisor-two-stage preview must not run stage2 without local model")

    openrouter_review_out = io.StringIO()
    with contextlib.redirect_stdout(openrouter_review_out):
        openrouter_review_rc = _cmd_research(["advisor-review", "--source", zip_source, "--provider", "openrouter", "--json"])
    _require(openrouter_review_rc == 0, "advisor-review OpenRouter preview must return 0 without model call")
    openrouter_review = parse_local_model_research_advisor_review_json(openrouter_review_out.getvalue())
    _require(openrouter_review["selected_provider"] == "openrouter" and openrouter_review["model_metadata"]["model_used"] is False,
             "OpenRouter advisor-review preview must not call model")

    invalid_err = io.StringIO()
    with contextlib.redirect_stderr(invalid_err):
        invalid_rc = _cmd_research(["advisor-review", "--source", zip_source, "--provider", "openrouter", "--local-model", "--json"])
    _require(invalid_rc != 0 and "cannot be combined" in invalid_err.getvalue(),
             "OpenRouter with --local-model must be rejected")

    for command in ("advisor-review", "advisor-comparison", "advisor-two-stage"):
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            write_rc = _cmd_research([command, "--source", zip_source, "--write"])
        _require(write_rc != 0 and "read-only" in err.getvalue(), f"research {command} --write must be rejected")
        missing_err = io.StringIO()
        with contextlib.redirect_stderr(missing_err):
            missing_rc = _cmd_research([command, "--json"])
        _require(missing_rc != 0 and "requires --source" in missing_err.getvalue(),
                 f"research {command} missing --source must be rejected")
        outside_err = io.StringIO()
        with contextlib.redirect_stderr(outside_err):
            outside_rc = _cmd_research([command, "--source", "../README.md", "--json"])
        _require(outside_rc != 0, f"research {command} outside source must be rejected")

    print("local model advisor CLIs OK")

