EXECUTION_DETERMINISTIC_CHECKS = EXECUTION_FAST_CHECKS + EXECUTION_DEEP_CHECKS


SOURCE_CORE_CHECKS = (
    check_growth_suite_selector_boundaries,
    check_research_target_intake_helpers,
    check_research_target_clis,
    check_source_aware_downstream_binding_helpers,
    check_source_aware_downstream_binding_clis,
    check_source_aware_archive_concept_extractor_helpers,
    check_growth_source_cache_module_extraction,
    check_growth_queue_e2e_cache_module_extraction,
    check_growth_source_suitability_module_extraction,
    check_growth_source_queue_module_extraction,
    check_growth_repo_role_calibration_module_extraction,
    check_growth_concept_confidence_module_extraction,
    check_growth_opportunity_scoring_module_extraction,
    check_growth_task_draft_alignment_module_extraction,
    check_growth_direct_upgrade_eval_module_extraction,
    check_growth_operator_qa_module_extraction,
    check_growth_operator_cache_dashboard_module_extraction,
)


SOURCE_EXTENDED_CHECKS = (
    check_source_aware_operator_report_and_sandbox_helpers,
    check_source_aware_operator_report_and_sandbox_clis,
    check_source_aware_control_plane_dashboard_helpers,
    check_source_aware_growth_e2e_summary_cache_helpers,
    check_source_aware_control_plane_dashboard_clis,
    check_source_aware_human_summary_clis,
    check_source_aware_provenance_specificity_helpers,
    check_source_aware_provenance_specificity_clis,
    check_source_aware_cross_target_specificity,
)


SOURCE_FAST_CHECKS = SOURCE_CORE_CHECKS + SOURCE_EXTENDED_CHECKS


def run_foundation_fast_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("foundation-fast"):
        _run_check_group(FOUNDATION_FAST_CHECKS)
    print("Growth pipeline foundation-fast suite passed")


def run_planning_core_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("planning-core", slow_threshold_seconds=5.0):
        _run_check_group(PLANNING_CORE_CHECKS)
    print("Growth pipeline planning-core suite passed")


def run_planning_extended_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("planning-extended", slow_threshold_seconds=15.0):
        _run_check_group(PLANNING_EXTENDED_CHECKS)
    print("Growth pipeline planning-extended suite passed")


def run_planning_fast_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("planning-fast", slow_threshold_seconds=15.0):
        _run_check_group(PLANNING_FAST_CHECKS)
    print("Growth pipeline planning-fast suite passed")


def run_planning_deep_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("planning-deep", slow_threshold_seconds=90.0):
        _run_check_group(PLANNING_DEEP_CHECKS)
    print("Growth pipeline planning-deep suite passed")


def run_planning_deterministic_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("planning-deterministic", slow_threshold_seconds=90.0):
        run_planning_fast_suite()
        run_planning_deep_suite()
    print("Growth pipeline planning-deterministic suite passed")


def run_execution_fast_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("execution-fast", slow_threshold_seconds=10.0):
        _run_check_group(EXECUTION_FAST_CHECKS)
    print("Growth pipeline execution-fast suite passed")


def run_execution_deep_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("execution-deep", slow_threshold_seconds=45.0):
        _run_check_group(EXECUTION_DEEP_CHECKS)
    print("Growth pipeline execution-deep suite passed")


def run_execution_deterministic_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("execution-deterministic", slow_threshold_seconds=45.0):
        run_execution_fast_suite()
        run_execution_deep_suite()
    print("Growth pipeline execution-deterministic suite passed")


def run_base_suite() -> None:
    with time_section("base", slow_threshold_seconds=20.0):
        run_foundation_fast_suite()
        run_planning_core_suite()
        run_execution_fast_suite()
    print("Growth pipeline base suite passed")


def run_source_core_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("source-core", slow_threshold_seconds=3.0):
        _run_check_group(SOURCE_CORE_CHECKS)
    print("Growth pipeline source-core suite passed")


def run_source_extended_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("source-extended", slow_threshold_seconds=8.0):
        _run_check_group(SOURCE_EXTENDED_CHECKS)
    print("Growth pipeline source-extended suite passed")


def run_source_fast_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("source-fast", slow_threshold_seconds=8.0):
        run_source_core_suite()
        run_source_extended_suite()
    print("Growth pipeline source-fast suite passed")


def run_source_slow_suite() -> None:
    _ensure_growth_test_setup()
    with time_section("source-slow"):
        check_slow_source_aware_real_archive_integration_helpers(force=True)
        check_local_model_advisor_foundation_helpers()
        check_local_model_advisor_clis()
    print("Growth pipeline source-slow suite passed")


def run_default_suite() -> None:
    started = time.perf_counter()
    run_base_suite()
    run_source_core_suite()
    _GROWTH_TEST_SKIPPED_SUITES.add("source-extended")
    print("source-extended: skipped; run --suite source-extended or --suite source-fast for broader source-aware tiny-fixture checks")
    if _run_extended_growth_planning_tests():
        run_planning_extended_suite()
    else:
        _GROWTH_TEST_SKIPPED_SUITES.add("planning-extended")
        print("planning-extended: skipped; run --suite planning-extended or --suite all for extended deterministic planning checks")
    if _run_deep_growth_planning_tests():
        run_planning_deep_suite()
    else:
        _GROWTH_TEST_SKIPPED_SUITES.add("planning-deep")
        print("planning-deep: skipped; run --suite planning-deep or --suite all for deep deterministic planning checks")
    if _run_deep_growth_execution_tests():
        run_execution_deep_suite()
    else:
        _GROWTH_TEST_SKIPPED_SUITES.add("execution-deep")
        print("execution-deep: skipped; run --suite execution-deep or --suite all for deep deterministic execution checks")
    if _run_slow_growth_archive_tests():
        run_source_slow_suite()
    else:
        _GROWTH_TEST_SKIPPED_SUITES.add("source-slow")
        print("source-slow: skipped; run --suite source-slow or set LINK_RUN_SLOW_GROWTH_ARCHIVE_TESTS=1")
    _print_growth_test_timing_summary(time.perf_counter() - started)
    print("Growth pipeline default suites passed")


def run_all_suites() -> None:
    started = time.perf_counter()
    run_base_suite()
    run_planning_extended_suite()
    run_planning_deep_suite()
    run_execution_deep_suite()
    run_source_fast_suite()
    run_source_slow_suite()
    _print_growth_test_timing_summary(time.perf_counter() - started)
    print("Growth pipeline all suites passed")


def _print_suite_list() -> None:
    print("Growth pipeline test suites:")
    print("  foundation-fast          Fast foundational deterministic checks.")
    print("  planning-core            Fastest deterministic planning/console checks.")
    print("  planning-extended        Broader deterministic planning/console checks.")
    print("  planning-fast            planning-core + planning-extended.")
    print("  planning-deep            Deeper deterministic planning/console checks.")
    print("  planning-deterministic   planning-fast + planning-deep.")
    print("  execution-fast           Fast deterministic execution/receipt checks.")
    print("  execution-deep           Deeper deterministic execution/fork/transcript checks.")
    print("  execution-deterministic  execution-fast + execution-deep.")
    print("  base                     foundation-fast + planning-core + execution-fast.")
    print("  source-core              Fastest source-aware tiny-fixture checks.")
    print("  source-extended          Broader source-aware tiny-fixture checks.")
    print("  source-fast              source-core + source-extended.")
    print("  source-slow              Real archive integration checks.")
    print("  all                      base + planning-extended + planning-deep + execution-deep + source-fast + source-slow.")
    print("Recommended commands:")
    print("  python3 tests/test_growth_pipeline.py --suite foundation-fast")
    print("  python3 tests/test_growth_pipeline.py --suite planning-core")
    print("  python3 tests/test_growth_pipeline.py --suite planning-fast")
    print("  python3 tests/test_growth_pipeline.py --suite execution-fast")
    print("  python3 tests/test_growth_pipeline.py --suite base")
    print("  python3 tests/test_growth_pipeline.py --suite source-core")
    print("  python3 tests/test_growth_pipeline.py --suite source-fast")
    print("  python3 tests/test_growth_pipeline.py --suite all")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Run deterministic Growth pipeline smoke test suites.")
    parser.add_argument("--suite", choices=("foundation-fast", "planning-core", "planning-extended", "planning-fast", "planning-deep", "planning-deterministic", "execution-fast", "execution-deep", "execution-deterministic", "base", "source-core", "source-extended", "source-fast", "source-slow", "all"), help="suite to run")
    parser.add_argument("--list-suites", action="store_true", help="list available suites and recommended commands")
    args = parser.parse_args(argv)
    if args.list_suites:
        _print_suite_list()
        return 0
    suite = args.suite
    started = time.perf_counter()
    if suite == "foundation-fast":
        run_foundation_fast_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "planning-core":
        run_planning_core_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "planning-extended":
        run_planning_extended_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "planning-fast":
        run_planning_fast_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "planning-deep":
        run_planning_deep_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "planning-deterministic":
        run_planning_deterministic_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "execution-fast":
        run_execution_fast_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "execution-deep":
        run_execution_deep_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "execution-deterministic":
        run_execution_deterministic_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "base":
        run_base_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "source-core":
        run_source_core_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "source-extended":
        run_source_extended_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "source-fast":
        run_source_fast_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "source-slow":
        run_source_slow_suite()
        _print_growth_test_timing_summary(time.perf_counter() - started)
        return 0
    if suite == "all":
        run_all_suites()
        return 0
    run_default_suite()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
